{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A Quiet Reprieve</title>
  <meta name="description" content="Gatherings and private practices of layered sound for measured rest in {{CITY}}, {{STATE}}. Small groups • Private sessions • Gentle series.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="site-shell">
    <header class="topbar">
      <div class="brand">
        <svg class="logo" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="22" fill="rgba(255,255,255,0.06)"/><path d="M12 28c4-8 20-8 24 0" stroke="rgba(255,255,255,0.45)" stroke-width="1.5" fill="none" stroke-linecap="round"/></svg>
        <div>
          <div class="name">{{BUSINESS_NAME}}</div>
          <div class="tag">A simple, attentive sound practice</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html">Gather</a>
        <a href="events.html">Events</a>
        <a href="private-sessions.html">Private Sessions</a>
        <a href="pricing.html">Offerings</a>
        <a href="about.html">Stories</a>
        <a href="faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="hero-inner">
          <h1>Brief sound practices for clearer breathing and steadier attention</h1>
          <p class="lead">An hour of layered tone, guided stillness, and careful ending. For those moments when rest needs shape and a kind of listening.</p>
          <div class="hero-actions">
            <a class="btn primary" href="events.html">See upcoming gatherings</a>
            <a class="btn ghost" href="book.html">Book a private session</a>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true">
          <svg viewBox="0 0 400 300" class="hero-svg">
            <defs>
              <pattern id="p1" patternUnits="userSpaceOnUse" width="80" height="80">
                <image xlink:href="assets/img/pattern.svg" x="0" y="0" width="80" height="80" />
              </pattern>
            </defs>
            <rect x="0" y="0" width="400" height="300" fill="url(#p1)" opacity="0.14"/>
          </svg>
        </div>
      </section>

      <section class="social-proof">
        <div class="wrap">
          <h2>Quiet endorsements</h2>
          <p class="sub">People come for the pause. Credibility lives in repeat visits and steady referrals.</p>

          <div class="proof-grid">
            <div class="gallery" id="testimonialGallery">
              <div class="testimonial" data-index="0">
                <blockquote>"A steady hour that lets thought soften — I left with a steadier breath and less hurry."</blockquote>
                <cite>— Mara, teacher</cite>
                <div class="badges">
                  <span class="badge" data-tip="Attended 12 gatherings">12+</span>
                  <span class="badge" data-tip="Local studio partner">Studio Partner</span>
                </div>
              </div>
              <div class="testimonial" data-index="1" aria-hidden="true">
                <blockquote>"Careful sounds. Short cues. I sleep better the next night."</blockquote>
                <cite>— Joel, designer</cite>
                <div class="badges">
                  <span class="badge" data-tip="Verified repeat guest">Repeat Guest</span>
                  <span class="badge" data-tip="Recommended by health coaches">Coach-Recommended</span>
                </div>
              </div>
              <div class="testimonial" data-index="2" aria-hidden="true">
                <blockquote>"Private session recalibrated my neck tension — a subtle, practical change."</blockquote>
                <cite>— Sam, editor</cite>
                <div class="badges">
                  <span class="badge" data-tip="Offers private work">Private Friendly</span>
                  <span class="badge" data-tip="Series available">Series</span>
                </div>
              </div>
              <div class="controls">
                <button id="prevTest">◀</button>
                <div class="dots" id="testDots"></div>
                <button id="nextTest">▶</button>
              </div>
            </div>

            <aside class="cred">
              <h3>Trusted by</h3>
              <ul class="logos">
                <li title="Community Health Collective">Community Health Collective</li>
                <li title="Northwell Arts">Northwell Arts</li>
                <li title="Local Yoga Co.">Local Yoga Co.</li>
              </ul>
              <p class="small">All testimonials are from consenting attendees. See full list on the stories page.</p>
            </aside>
          </div>
        </div>
      </section>

      <section class="benefits">
        <div class="wrap">
          <h2>How this practice meets your day</h2>
          <ul class="benefit-list">
            <li>
              <strong>Concise structure</strong>
              <p>One clear arc: arrival, sonic work, gentle re-orientation. No excessive ceremony.</p>
            </li>
            <li>
              <strong>Grounded tools</strong>
              <p>Breath cues, light movement, and layered tones for steady physiological effect.</p>
            </li>
            <li>
              <strong>Adaptable offerings</strong>
              <p>Group gatherings, private sessions, and short series—choose what fits your rhythm.</p>
            </li>
          </ul>
        </div>
      </section>

      <section class="process">
        <div class="wrap">
          <h2>What to expect</h2>
          <ol class="process-steps">
            <li>
              <strong>Arrival & settling</strong>
              <p>Low lighting, cushions, a brief check-in. Comfort is primary.</p>
            </li>
            <li>
              <strong>Layered sound</strong>
              <p>Bowls, subtle drones, and voice cues designed to let attention widen and soften.</p>
            </li>
            <li>
              <strong>Measured close</strong>
              <p>A clear ending so you can return to your day steady and attentive.</p>
            </li>
          </ol>
          <p class="disclaimer">Contraindications: If you are pregnant, have epilepsy, or have a diagnosed sensitivity to sustained auditory stimulation, consult your clinician before attending. Contact us at {{EMAIL}} for accommodations.</p>
        </div>
      </section>

      <section class="micro-pricing">
        <div class="wrap">
          <h2>Choose a frame</h2>
          <p class="sub">Toggle the view to compare single-session subscription pricing with bundled series pricing.</p>

          <div class="toggle-row">
            <div class="toggle">
              <label class="switch">
                <input type="checkbox" id="priceToggle" aria-label="Toggle pricing view">
                <span class="slider"></span>
              </label>
              <div class="toggle-labels"><span>Monthly</span><span>Package</span></div>
            </div>

            <div class="pricing-cards">
              <div class="card">
                <h3>Flow Subscription</h3>
                <p class="muted">One monthly payment for weekly gatherings</p>
                <div class="price" data-month="29" data-package="240">$<span class="num" id="priceA">29</span><span class="suffix">/mo</span></div>
                <a href="pricing.html" class="btn">Join the Flow</a>
              </div>

              <div class="card accent">
                <h3>Sustained Series</h3>
                <p class="muted">Six-session package for steady benefit</p>
                <div class="price" data-month="160" data-package="120">$<span class="num" id="priceB">160</span><span class="suffix"> per series</span></div>
                <a href="pricing.html" class="btn">Reserve a series</a>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section class="cta-final">
        <div class="wrap">
          <h2>Still deciding?</h2>
          <p class="sub">Try a single gathering or request a private session for tailored care.</p>
          <div class="cta-actions">
            <a class="btn primary" href="events.html">Find a gathering</a>
            <a class="btn ghost" href="book.html">Request private time</a>
          </div>
        </div>
      </section>

      <section class="faq">
        <div class="wrap">
          <h2>Questions</h2>
          <div class="qa">
            <details>
              <summary>What should I bring?</summary>
              <p>Bring whatever makes you comfortable: mat, cushion, a light blanket. We provide basic props on request.</p>
            </details>
            <details>
              <summary>Is this religious or therapeutic?</summary>
              <p>Sessions are non-religious. They are not a substitute for clinical therapy. If you have mental health concerns, consult a provider.</p>
            </details>
            <details>
              <summary>Are refunds available?</summary>
              <p>Single gatherings may be transferrable up to 24 hours before start. Series and subscriptions follow the terms on the offerings page.</p>
            </details>
          </div>
        </div>
      </section>

    </main>

    <footer class="site-footer">
      <div class="wrap">
        <div class="col">
          <strong>{{BUSINESS_NAME}}</strong>
          <p>{{TAGLINE}}</p>
        </div>
        <div class="col">
          <p>Contact</p>
          <p><a href="tel:{{PHONE}}">{{PHONE}}</a><br/><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div class="col small">
          <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}}</p>
        </div>
      </div>
    </footer>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
