{"path":"assets/css/styles.css","content":":root{--bg:#0f1720;--glass:rgba(255,255,255,0.06);--muted:rgba(255,255,255,0.6);--accent:#b8ffe6;--accent-2:#7bd9ff;--card:#0f1725}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6f3ef;background:linear-gradient(180deg,#081018 0%,#081a20 60%);background-attachment:fixed}
.site-shell{min-height:100vh;display:flex;flex-direction:column}
.topbar{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px);border-bottom:1px solid rgba(255,255,255,0.03)}
.brand{display:flex;gap:12px;align-items:center}
.logo{width:44px;height:44px}
.brand .name{font-weight:700}
.brand .tag{font-size:12px;opacity:.8}
.nav a{color:var(--muted);margin-left:16px;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#022;font-weight:700}
.hero{display:flex;align-items:stretch;gap:20px;padding:56px 28px}
.hero-inner{flex:1;max-width:720px}
.hero h1{font-size:36px;margin:0 0 10px 0}
.lead{color:var(--muted);margin:0 0 18px 0}
.hero-actions .btn{margin-right:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;background:transparent;color:var(--muted);border:1px solid rgba(255,255,255,0.06)}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#012}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06)}
.hero-art{width:320px}
.hero-svg{width:100%;height:auto;border-radius:14px}
.wrap{max-width:1100px;margin:0 auto;padding:40px 20px}
.social-proof{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-top:1px solid rgba(255,255,255,0.02)}
.proof-grid{display:flex;gap:28px;align-items:flex-start}
.gallery{flex:2;background:var(--glass);padding:18px;border-radius:12px;backdrop-filter:blur(6px);}
.gallery .testimonial{padding:12px}
.gallery blockquote{margin:0 0 8px 0;font-style:italic;color:#ddf6ee}
.gallery cite{color:var(--muted);font-size:13px}
.badges{margin-top:10px}
.badge{display:inline-block;background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;margin-right:6px;font-size:12px;color:var(--muted);cursor:default}
.controls{display:flex;align-items:center;gap:8px;margin-top:12px}
.controls button{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:6px;border-radius:8px}
.cred{flex:1;background:rgba(255,255,255,0.02);padding:16px;border-radius:12px}
.cred h3{margin-top:0}
.logos{list-style:none;padding:0;margin:12px 0 0 0}
.logos li{padding:8px 6px;background:rgba(255,255,255,0.02);border-radius:8px;margin-bottom:8px;color:var(--muted);font-size:13px}
.benefits{padding-top:12px}
.benefit-list{display:flex;gap:20px;list-style:none;padding:0;margin:12px 0}
.benefit-list li{background:var(--card);padding:14px;border-radius:12px;flex:1}
.process{background:linear-gradient(180deg,transparent,rgba(0,0,0,0.02));}
.process-steps{display:flex;gap:18px;list-style:none;padding:0}
.process-steps li{background:var(--glass);padding:14px;border-radius:10px}
.disclaimer{font-size:13px;color:var(--muted);margin-top:10px}
.micro-pricing .toggle-row{display:flex;align-items:center;justify-content:space-between;gap:20px}
.toggle{display:flex;align-items:center;gap:12px}
.switch{position:relative;display:inline-block;width:52px;height:28px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:rgba(255,255,255,0.06);border-radius:28px}
.slider:before{position:absolute;content:"";height:22px;width:22px;left:4px;top:3px;background:white;border-radius:50%;transition:transform .28s}
.switch input:checked + .slider{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
.switch input:checked + .slider:before{transform:translateX(24px)}
.toggle-labels{display:flex;gap:6px;color:var(--muted);font-size:13px}
.pricing-cards{display:flex;gap:16px}
.card{background:var(--glass);padding:16px;border-radius:12px;width:220px;text-align:center}
.card.accent{background:linear-gradient(180deg,rgba(184,255,230,0.06),rgba(123,217,255,0.03));}
.price{font-size:22px;margin:12px 0}
.price .num{font-weight:800}
.cta-final{padding:30px 0}
.faq{background:var(--card);padding:28px;border-top:1px solid rgba(255,255,255,0.02)}
.qa details{background:rgba(255,255,255,0.02);padding:12px;border-radius:8px;margin-bottom:8px}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:18px 28px;margin-top:auto}
.site-footer .wrap{display:flex;gap:20px;align-items:flex-start}
.site-footer .col{flex:1}
.small{font-size:13px;color:var(--muted)}
@media(max-width:880px){
  .hero{flex-direction:column}
  .proof-grid{flex-direction:column}
  .benefit-list{flex-direction:column}
  .process-steps{flex-direction:column}
  .pricing-cards{flex-direction:column}
}
/* Tooltip */
.badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;background:#012;color:var(--accent);padding:6px 8px;border-radius:6px;font-size:12px;margin-top:22px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qp(selector, ctx){ return (ctx||document).querySelector(selector) }
  function qpa(selector, ctx){ return Array.from((ctx||document).querySelectorAll(selector)) }

  // Year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Testimonial gallery
  const gallery = qp('#testimonialGallery');
  const tests = qpa('.gallery .testimonial');
  const dots = qp('#testDots');
  const prevBtn = qp('#prevTest');
  const nextBtn = qp('#nextTest');
  let current = 0;
  let galleryTimer = null;

  function makeDots(){
    dots.innerHTML = '';
    tests.forEach((t,i)=>{
      const d = document.createElement('button');
      d.className = 'dot';
      d.setAttribute('aria-label','Show testimonial '+(i+1));
      d.textContent = i+1;
      d.addEventListener('click',()=>show(i));
      dots.appendChild(d);
    });
    updateDots();
  }
  function updateDots(){
    qpa('.dot', dots).forEach((d,i)=> d.classList.toggle('active', i===current));
  }
  function show(i){
    tests.forEach((t,idx)=>{
      t.style.display = idx===i? 'block' : 'none';
      t.setAttribute('aria-hidden', idx===i? 'false' : 'true');
    });
    current = i;
    updateDots();
    resetTimer();
  }
  function next(){ show((current+1) % tests.length) }
  function prev(){ show((current-1+tests.length) % tests.length) }
  function resetTimer(){ if(galleryTimer) clearInterval(galleryTimer); galleryTimer = setInterval(next,5000) }

  makeDots(); show(0);
  prevBtn.addEventListener('click', prev);
  nextBtn.addEventListener('click', next);

  // Badge tooltips (small custom enhancement)
  document.querySelectorAll('.cred .logos li').forEach(li=>{
    li.addEventListener('mouseenter', (e)=>{
      const tip = document.createElement('div');
      tip.className = 'org-tip';
      tip.textContent = li.getAttribute('title') || li.textContent;
      tip.style.position = 'absolute';
      tip.style.background = '#022';
      tip.style.color = '#b8ffe6';
      tip.style.padding = '6px 8px';
      tip.style.borderRadius = '6px';
      tip.style.fontSize = '12px';
      document.body.appendChild(tip);
      function move(ev){ tip.style.left = (ev.pageX + 12) + 'px'; tip.style.top = (ev.pageY + 12) + 'px'; }
      move(e);
      li._move = move;
      li.addEventListener('mousemove', move);
      li._tip = tip;
    });
    li.addEventListener('mouseleave', ()=>{
      if(li._tip){ document.body.removeChild(li._tip); li.removeEventListener('mousemove', li._move); li._tip = null }
    });
  });

  // Pricing comparator toggle with animated numbers
  const toggle = qp('#priceToggle');
  const priceA = qp('#priceA');
  const priceB = qp('#priceB');

  function animateNumber(el, from, to, duration){
    const start = performance.now();
    function frame(now){
      const t = Math.min(1, (now-start)/duration);
      const val = Math.round(from + (to-from) * (1 - Math.cos(t * Math.PI)) / 2); // ease
      el.textContent = val;
      if(t < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  function refreshPrices(){
    const isPackage = toggle.checked;
    // Read data attributes
    const aMonth = Number(priceA.parentNode.getAttribute('data-month'));
    const aPack = Number(priceA.parentNode.getAttribute('data-package'));
    const bMonth = Number(priceB.parentNode.getAttribute('data-month'));
    const bPack = Number(priceB.parentNode.getAttribute('data-package'));

    animateNumber(priceA, Number(priceA.textContent), isPackage ? aPack : aMonth, 600);
    animateNumber(priceB, Number(priceB.textContent), isPackage ? bPack : bMonth, 600);
    // Suffix adjustments
    priceA.parentNode.querySelector('.suffix').textContent = isPackage ? ' per series' : '/mo';
    priceB.parentNode.querySelector('.suffix').textContent = isPackage ? ' per series' : '/mo';
  }

  toggle.addEventListener('change', refreshPrices);

  // Initialize timer
  resetTimer();

  // Lightweight accessibility: allow left/right arrows to navigate gallery
  document.addEventListener('keydown', function(e){
    if(e.key === 'ArrowLeft') prev();
    if(e.key === 'ArrowRight') next();
  });

  // Next-event teaser (small, local module)
  // In a real site this would be dynamic; here we mock a next event.
  const nextEvent = { title: 'Community Session — Early Evening', date: '2026-03-05', time: '18:30', location: '{{CITY}}' };
  const eventEl = document.createElement('div');
  eventEl.className = 'next-event';
  eventEl.innerHTML = '<strong>Next: </strong>' + nextEvent.title + ' • ' + nextEvent.date + ' • ' + nextEvent.time + ' • ' + nextEvent.location + ' <a href="events.html">See calendar</a>';
  document.querySelector('.wrap').insertAdjacentElement('afterbegin', eventEl);
})();"} 
